var n=`0820-papa-and-moroho`;var t=`world-0820`;var o=`LS`;var s=`southern-africa`;var a=4;var r=42;var l={en:`Papa and Moroho`,ua:`Папа з морохо`};var g={en:`Papa and Moroho is a Lesotho dish made with cornmeal, yellow onion, collard greens, lemon juice. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Папа з морохо, страва кухні країни Лесото. Основні складники: кукурудзяна крупа дрібного помелу, жовта цибуля, листова капуста колард, лимонний сік. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`water`,900,`ml`],[`table-salt`,5,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 22 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 22 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:22,i:[[`cornmeal`,400,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,130,`g`],[`collard-greens`,400,`g`],[`sunflower-oil`,30,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`lemon-juice`,20,`ml`]]}];var m={slug:n,id:t,country:`LS`,region:s,servings:4,minutes:42,title:l,text:g,steps:d};export{o as country,m as default,t as id,r as minutes,s as region,a as servings,n as slug,d as steps,g as text,l as title};